import 'package:flutter/material.dart';\nimport '../../config/theme/app_theme.dart';\n\nclass RouteViewerScreen extends StatefulWidget {\n  const RouteViewerScreen({Key? key}) : super(key: key);\n\n  @override\n  State<RouteViewerScreen> createState() => _RouteViewerScreenState();\n}\n\nclass _RouteViewerScreenState extends State<RouteViewerScreen> {\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('Saved Routes'),\n        backgroundColor: AppTheme.backgroundColor,\n      ),\n      backgroundColor: AppTheme.backgroundColor,\n      body: ListView(\n        padding: const EdgeInsets.all(16),\n        children: [\n          _buildRouteCard(\n            title: 'Morning Trek',\n            distance: '12.5 km',\n            time: '3h 45min',\n            difficulty: 'Medium',\n          ),\n          _buildRouteCard(\n            title: 'Mountain Route',\n            distance: '18.3 km',\n            time: '5h 20min',\n            difficulty: 'Hard',\n          ),\n          _buildRouteCard(\n            title: 'River Trail',\n            distance: '8.2 km',\n            time: '2h 15min',\n            difficulty: 'Easy',\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildRouteCard({\n    required String title,\n    required String distance,\n    required String time,\n    required String difficulty,\n  }) {\n    return Card(\n      color: AppTheme.surfaceColor,\n      margin: const EdgeInsets.only(bottom: 12),\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Text(\n              title,\n              style: const TextStyle(\n                color: AppTheme.primaryColor,\n                fontSize: 18,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n            const SizedBox(height: 12),\n            Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                _buildInfoChip('Distance', distance),\n                _buildInfoChip('Time', time),\n                _buildInfoChip('Level', difficulty),\n              ],\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildInfoChip(String label, String value) {\n    return Column(\n      children: [\n        Text(\n          label,\n          style: const TextStyle(\n            color: AppTheme.textTertiary,\n            fontSize: 12,\n          ),\n        ),\n        Text(\n          value,\n          style: const TextStyle(\n            color: AppTheme.primaryColor,\n            fontSize: 14,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n      ],\n    );\n  }\n}\n